<?php

declare(strict_types=1);
session_start(); header('Content-Type: application/json; charset=utf-8'); require_once __DIR__ . '/../../../config/database.php';
$userId = (int) ($_SESSION['user_id'] ?? 0); if ($userId < 1) { http_response_code(401); echo json_encode(['error' => 'Authentification requise.']); exit; } $user = $pdo->prepare("SELECT role FROM users WHERE id = :id AND is_active = 1 LIMIT 1"); $user->execute(['id' => $userId]); if ($user->fetchColumn() !== 'client') { http_response_code(403); echo json_encode(['error' => 'Accès réservé aux clients.']); exit; }
try { $quotes = $pdo->prepare('SELECT id, quote_type, title, description, category, city, estimated_budget, deadline, project_address, status, created_at FROM quotes WHERE client_id = :client_id ORDER BY created_at DESC'); $quotes->execute(['client_id' => $userId]); $responseStatement = $pdo->prepare("SELECT qr.id, qr.proposed_amount, qr.estimated_days, qr.message, qr.status, CONCAT(u.first_name, ' ', u.last_name) AS artisan_name FROM quote_responses qr INNER JOIN artisan_profiles ap ON ap.id = qr.artisan_id INNER JOIN users u ON u.id = ap.user_id WHERE qr.quote_id = :quote_id ORDER BY qr.proposed_amount ASC"); $data = []; foreach ($quotes->fetchAll() as $quote) { $responseStatement->execute(['quote_id' => $quote['id']]); $quote['id'] = (int) $quote['id']; $quote['estimated_budget'] = $quote['estimated_budget'] !== null ? (float) $quote['estimated_budget'] : null; $quote['responses'] = array_map(static function (array $response): array { return ['id' => (int) $response['id'], 'amount' => (float) $response['proposed_amount'], 'days' => (int) $response['estimated_days'], 'message' => $response['message'], 'status' => $response['status'], 'artisanName' => $response['artisan_name']]; }, $responseStatement->fetchAll()); $data[] = $quote; } echo json_encode(['success' => true, 'data' => $data]); } catch (PDOException $exception) { http_response_code(500); echo json_encode(['error' => 'Impossible de charger les devis.']); }
